scripts.script:
const jiaoyi = actor.system.skills.jiaoyi.total || 0;
const eff = thisItem.effects.getName("算盘").toObject();
delete eff._id;
eff.origin = thisItem.uuid;
eff.changes[0].value = String(jiaoyi);
await game.xjzl.api.effects.addEffect(actor, eff);
ui.notifications.info(`算盘开启：招式伤害 +${jiaoyi}`);

if (args.isBroken) {
    const ratio = 10 + (Math.max(1, move.computedLevel || 1) - 1) * 10;
    ChatMessage.create({
        content: `<div class="xjzl-chat-card">
            <div class="card-header" style="border-bottom:1px solid #ccc; font-weight:bold;">秋后算账 - 击破触发</div>
            <div style="padding:5px; font-size:0.9em;">
                <p>目标应掉落行囊中 <b>${ratio}%</b> 的银两。</p>
                <p><i>请GM手动处理掉落。</i></p>
            </div>
        </div>`,
        speaker: ChatMessage.getSpeaker({actor: actor})
    });
}

const silver = actor.system.resources.silver || 0;
const bonus = Math.min(100, Math.floor(silver / 100));
const eff = thisItem.effects.getName("万利").toObject();
delete eff._id;
eff.origin = thisItem.uuid;
eff.changes[0].value = String(bonus);
await game.xjzl.api.effects.addEffect(actor, eff);
ui.notifications.info(`一本万利：获得伤害加成 +${bonus}`);

const silver = actor.system.resources.silver || 0;
const lvl = Math.max(1, move.computedLevel || 1);
const baseCap = 20 + (lvl - 1) * 5;
const caiqi = Math.min(baseCap, Math.ceil(silver / 1000));

const eff = thisItem.effects.getName("财气值").toObject();
delete eff._id;
eff.origin = thisItem.uuid;
eff.changes[0].value = String(caiqi);
eff.changes[1].value = String(caiqi);
// 将财气值存入Flag供其他招式调用
eff.flags["xjzl-system"].caiqiValue = caiqi;

await game.xjzl.api.effects.addEffect(actor, eff);
ui.notifications.info(`财大气粗：获得财气值 ${caiqi}`);

const caiqiEff = actor.effects.find(e => e.getFlag("xjzl-system", "slug") === "caiqi");
if (caiqiEff) {
    const caiqiVal = caiqiEff.getFlag("xjzl-system", "caiqiValue") || 0;
    if (caiqiVal > 0) {
        const confirm = await foundry.applications.api.DialogV2.confirm({
            window: { title: "堆金积玉" },
            content: `<p>当前财气值：<b>${caiqiVal}</b></p><p>是否掷出等额银两以增加伤害？</p><p style="color:red; font-size:0.8em;">(银两扣除请手动操作)</p>`,
            yes: { label: "掷出 (+伤害)", icon: "fas fa-coins" },
            no: { label: "保留", icon: "fas fa-times" }
        });

        if (confirm) {
            args.flags.damageResult.damage += caiqiVal;
            args.flags.damageResult.breakdown += `\n+ 掷金加伤: ${caiqiVal}`;
            ui.notifications.info(`已掷出 ${caiqiVal} 两白银！`);
        }
    }
}

const confirm = await foundry.applications.api.DialogV2.confirm({
    window: { title: "生财有道" },
    content: `<p>是否进行了 [交易] 对抗并获胜？</p>`,
    yes: { label: "获胜 (+3虚招)", icon: "fas fa-check" },
    no: { label: "未进行/失败", icon: "fas fa-times" }
});

if (confirm) {
    args.flags.bonusFeint += 3;
}

if (args.isBroken) {
    const eff = thisItem.effects.getName("散财").toObject();
    delete eff._id;
    eff.origin = thisItem.uuid;
    eff.duration = { rounds: 3 };
    await game.xjzl.api.effects.addEffect(args.target, eff);
    ui.notifications.info(`${args.target.name} 陷入散财状态！`);
}

const lvl = Math.max(1, args.move.computedLevel || 1);
// 基础1 + (等级-1)*1 = 等级
// 或者理解为每级+1
actor.system.skills.jiaoyi.mod += lvl;

const lvl = Math.max(1, move.computedLevel || 1);
const maxDarts = 5 + (lvl - 1) * 5;

// 弹窗询问
const count = await foundry.applications.api.DialogV2.prompt({
    window: { title: "金钱镖" },
    content: `<div style="text-align:center;"><p>最大投掷数: ${maxDarts}</p><label>投掷数量 (请自觉扣除 50两/枚)</label><input type="number" name="count" value="1" min="1" max="${maxDarts}" autofocus></div>`,
    ok: { callback: (event, button) => button.form.elements.count.value }
});

const num = Math.min(maxDarts, Math.max(1, parseInt(count) || 1));

// 设置固定流失伤害
args.output.damage = num * 10;
args.output.bonusDesc.push(`投掷 ${num} 枚 (应耗银 ${num*50})`);

const targetShihao = args.target.system.social?.shihao || [];
const moneyHobbies = ["weapon", "clothes", "jewelry", "money", "antique"];
// 检查是否有交集
const hasHobby = targetShihao.some(h => moneyHobbies.includes(h));
if (hasHobby) {
    args.flags.forceHit = true;
}

let goldItemsCount = 0;
for (const i of actor.items) {
    if (i.system.quality >= 3) goldItemsCount++;
}
const lvl = Math.max(1, move.computedLevel || 1);
const maxShencai = 10 + (lvl - 1) * 5;
const shencaiBonus = Math.min(goldItemsCount, maxShencai);
S.stats.shencai.mod += shencaiBonus;

let lvl = 1;
const item = actor.items.find(i => i.name === '物华天宝' && i.type === 'wuxue');
if (item) {
    const move = item.system.moves.find(m => m.name === '物华天宝');
    if (move) lvl = Math.max(1, move.computedLevel || 1);
}
const reduct = 10 + (lvl - 1) * 5;
args.output.damage = Math.max(0, args.output.damage - reduct);

if (!Macros.checkStance(actor, args)) return;
const eff = thisItem.effects.getName('刚劲').toObject();
delete eff._id;
eff.origin = thisItem.uuid;
await game.xjzl.api.effects.addEffect(actor, eff);

if (!args.isHit) return;
const eff = CONFIG.statusEffects.find(e => e.id === 'unstable');
if (eff) {
    const data = foundry.utils.deepClone(eff);
    data.duration = { rounds: 1 };
    await game.xjzl.api.effects.addEffect(args.target, data);
}

const eff = thisItem.effects.getName('棍势').toObject();
delete eff._id;
eff.origin = thisItem.uuid;
await game.xjzl.api.effects.addEffect(actor, eff);

const gunshi = actor.effects.find(e => e.getFlag('xjzl-system', 'slug') === 'gunshi');
if (gunshi) {
    ui.notifications.info('提示：可手动移除 1 层 [棍势] 使本次招式释放距离+3。');
}

const xiayi = actor.system.social?.xiayi || 0;
const bonus = Math.floor(xiayi / 100) * 5;
args.output.damage += bonus;
args.output.bonusDesc.push(`侠义加伤 +${bonus}`);

if (args.outcome.isBroken) {
    // 既然击破了，本次攻击应当视为对方已破甲（无视防御）
    args.config.ignoreDefense = true;
}

if (args.isBroken) {
    const eff = CONFIG.statusEffects.find(e => e.id === "pojia");
    if(eff) {
        const data = foundry.utils.deepClone(eff);
        data.duration = { rounds: 3 };
        await game.xjzl.api.effects.addEffect(args.target, data);
        ui.notifications.info(`${args.target.name} 被破甲！`);
    }
}

const eff = thisItem.effects.getName("是").toObject();
delete eff._id;
eff.origin = thisItem.uuid;
await game.xjzl.api.effects.addEffect(args.target, eff);
ui.notifications.info(`${args.target.name} 获得了 [是] 评价。`);

// 检查攻击者是否为[侠]：侠义>=100 且 恶行<50
const attSocial = args.attacker?.system?.social;
if (attSocial && attSocial.xiayi >= 100 && attSocial.exing < 50) {
    args.output.damage += 10;
    if (args.output.bonusDesc) args.output.bonusDesc.push("明是非[否]：遭侠者惩戒 (+10)");
}

const lvl = Math.max(1, move.computedLevel || 1);
const block = 10 + (lvl - 1) * 5;
const crit = -1 + (lvl - 1) * -1;

const eff = thisItem.effects.getName('侠胆').toObject();
delete eff._id;
eff.origin = thisItem.uuid;
eff.duration = { rounds: 3 };

// 正确的动态设值：遍历 changes
eff.changes.forEach(c => {
    if (c.key === 'system.combat.block') c.value = String(block);
    if (c.key === 'system.combat.crit_waigong' || c.key === 'system.combat.crit_neigong') c.value = String(crit);
});

await game.xjzl.api.effects.addEffect(actor, eff);

const xiayi = actor.system.social.xiayi || 0;
if (xiayi >= 5) {
    await actor.update({'system.social.xiayi': xiayi - 5});
    actor.showFloatyText('-5 侠义 (维持)', {fill: '#0000FF', fontSize: 24});
    ChatMessage.create({
        content: `<div class="xjzl-chat-card"><b>侠胆</b>: 消耗 5 点侠义值维持状态 (剩余 ${xiayi - 5})。</div>`,
        speaker: ChatMessage.getSpeaker({actor: actor})
    });
} else {
    ui.notifications.warn(`${actor.name} 侠义值不足，侠胆消散！`);
    await thisEffect.delete();
}

// 1. 抛掷检定
const doPaozhi = await foundry.applications.api.DialogV2.confirm({
    window: { title: "撒手锏 - 抛掷" },
    content: "<p>是否进行 <b>[抛掷]</b> 检定以增加伤害？</p>",
    yes: { label: "投掷", icon: "fas fa-dice-d20" },
    no: { label: "跳过", icon: "fas fa-forward" }
});

if (doPaozhi) {
    // 调用 Actor 的检定方法
    const roll = await actor.rollAttributeTest("paozhi", { chatMessage: true });
    if (roll) {
        const bonus = roll.total;
        args.flags.damageResult.damage += bonus;
        args.flags.damageResult.breakdown += `\n+ 抛掷检定: ${bonus}`;
    }
}

// 2. 反应动作判定 (暴击)
const noReaction = await foundry.applications.api.DialogV2.confirm({
    window: { title: "撒手锏 - 暴击判定" },
    content: "<p>目标是否 <b>没有反应动作</b>？</p>",
    yes: { label: "是 (必暴)", icon: "fas fa-skull" },
    no: { label: "否 (正常)", icon: "fas fa-times" }
});

if (noReaction) {
    // 提高暴击阈值修正，使其极易暴击 (例如 +50)
    args.flags.critThresholdMod += 50;
    ui.notifications.info("目标无反应动作，招式必定暴击！");
}
